const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry for southern African countries
  const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.inList('country_na', ['Namibia', 'Botswana', 'Lesotho']));

  // 2. Data Acquisition - CHIRPS precipitation
  // Target period: Dec 2018 + Jan 2019
  const targetPeriod = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate('2018-12-01', '2019-02-01')
    .filterBounds(countries);

  // Baseline period: Dec+Jan for 2000-2019 (20 years)
  const baselinePeriod = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate('2000-12-01', '2020-02-01')
    .filter(ee.Filter.calendarRange(12, 1, 'month'))
    .filterBounds(countries);

  // Check collection sizes
  const targetSize = targetPeriod.size().getInfo();
  const baselineSize = baselinePeriod.size().getInfo();

  console.log(`Target period images: ${targetSize}`);
  console.log(`Baseline period images: ${baselineSize}`);

  if (targetSize === 0 || baselineSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean precipitation
  // Target period mean
  const targetMean = targetPeriod.sum()
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: countries,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

  // Baseline period mean (annual Dec+Jan means, then average those)
  const baselineAnnualMeans = ee.ImageCollection(
    ee.List.sequence(2000, 2019).map(function(year) {
      const decJan = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
        .filterDate(ee.Date.fromYMD(year, 11, 1), ee.Date.fromYMD(year+1, 1, 31))
        .sum();
      return decJan.set('year', year);
    })
  );

  const baselineMean = baselineAnnualMeans.mean()
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: countries,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

  // Check for valid pixels
  const targetCount = targetPeriod.sum()
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: countries,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

  const baselineCount = baselineAnnualMeans.mean()
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: countries,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

  console.log(`Target pixels: ${targetCount}, Baseline pixels: ${baselineCount}`);

  if (targetCount === 0 || baselineCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Validation & Final Answer
  console.log(`Target mean: ${targetMean?.toFixed(2)} mm`);
  console.log(`Baseline mean: ${baselineMean?.toFixed(2)} mm`);

  if (targetMean === null || baselineMean === null || 
      isNaN(targetMean) || isNaN(baselineMean)) {
    console.log("<answer>C3</answer>");
  } else if (targetMean < baselineMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
